public static FileFormat Detect(Stream stream, string fileName)
{
    if (fileName != null)
    {
        var ext = Path.GetExtension(fileName);
        return GetFormatByExtension(ext);
    }
    throw new ArgumentException("Cannot detect file format without file name");
}

